 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import fs from 'node:fs'
import { normalize, resolve, ComponentError, BaseNoSchemeError } from './uri.js'

function splitLines(text) {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
  fail('usage: cli.js normalize|resolve')
}

const input = fs.readFileSync(0, 'utf8')
const lines = splitLines(input)
const results = []

for (let i = 0; i < lines.length; i++) {
  const lineNum = i + 1
  try {
    if (mode === 'normalize') {
      results.push(normalize(lines[i]))
    } else {
      const idx = lines[i].indexOf(' ')
      if (idx === -1) {
        fail(`line ${lineNum}: expected a base and a reference`)
      }
      const base = lines[i].slice(0, idx)
      const ref = lines[i].slice(idx + 1)
      results.push(resolve(base, ref))
    }
  } catch (e) {
    if (e instanceof ComponentError) {
      fail(`line ${lineNum}: ${e.message}`)
    } else if (e instanceof BaseNoSchemeError) {
      fail(`line ${lineNum}: ${e.message}`)
    } else {
      throw e
    }
  }
}

process.stdout.write(results.map((line) => line + '\n').join(''))
